async def act(page):
    import re
    # Check for search bar or search-related elements on current page
    search_bar = page.get_by_role("searchbox")
    if await search_bar.count() == 0:
        search_bar = page.get_by_role("textbox", name="Search")
    if await search_bar.count() == 0:
        search_bar = page.get_by_role("textbox", name="search")
    if await search_bar.count() == 0:
        search_bar = page.get_by_role("textbox", name=re.compile(r"search", re.IGNORECASE))
    if await search_bar.count() == 0:
        search_bar = page.get_by_role("textbox").filter(has_text="")

    if await search_bar.count() == 0:
        # No search bar found on current page, navigate to home page directly
        await page.goto("http://localhost:8000/")
        await page.wait_for_load_state("networkidle")
        # Look for search bar again on the new page
        search_bar = page.get_by_role("searchbox")
        if await search_bar.count() == 0:
            search_bar = page.get_by_role("textbox", name="Search")
        if await search_bar.count() == 0:
            search_bar = page.get_by_role("textbox", name="search")
        if await search_bar.count() == 0:
            search_bar = page.get_by_role("textbox", name=re.compile(r"search", re.IGNORECASE))
        if await search_bar.count() == 0:
            search_bar = page.get_by_role("textbox").filter(has_text="")

    # Fill search bar with 'reveals'
    await search_bar.first.fill("reveals")

    # Submit search: look for a search button or press Enter
    search_button = page.get_by_role("button", name="Search")
    if await search_button.count() == 0:
        search_button = page.get_by_role("button", name="search")
    if await search_button.count() == 0:
        search_button = page.get_by_role("button", name=re.compile(r"search", re.IGNORECASE))
    if await search_button.count() > 0:
        await search_button.first.click()
    else:
        await search_bar.first.press("Enter")

    await page.wait_for_load_state("networkidle")

    # Identify search results; assume they are links within a main or list role
    results_container = page.get_by_role("main")
    if await results_container.count() == 0:
        results_container = page.get_by_role("list")
    if await results_container.count() == 0:
        results_container = page  # Fallback to entire page

    results = results_container.get_by_role("link")
    if await results.count() >= 3:
        await results.nth(2).click()  # Zero-indexed: nth(2) is the third result
    else:
        raise Exception("Less than 3 search results found.")

    await page.wait_for_load_state("networkidle")

